def v5_batch_registered_descriptor(root,name,expected_files):
    name = safe_name(name)
    require(name in expected_files,'batch-parent-v5-registered-file:' + name)
    expected = expected_files[name]
    require(canonical(pin(root / name,name)) == canonical(expected),'batch-parent-v5-actual-file-pin:' + name)
    return copy.deepcopy(expected)


def v5_batch_saved_manifest(folder,suffix):
    value = sealed(folder / 'manifest.json',V5_BATCH_SCHEMA + '.' + suffix)
    require(value.get('eof',True) is True and type(value['files']) is list,'batch-parent-v5-manifest-full-EOF')
    names = []
    for entry in value['files']:
        require(type(entry) is dict and set(entry) in ({'file','bytes','sha256'},
            {'file','bytes','sha256','dtype','shape'}),'batch-parent-v5-manifest-descriptor-shape')
        name = safe_name(entry['file'])
        require('/' not in name and type(entry['bytes']) is int and entry['bytes'] >= 0 and
            type(entry['sha256']) is str and HEX.fullmatch(entry['sha256']) is not None,
            'batch-parent-v5-manifest-descriptor-types')
        require(canonical(pin(folder / name,name)) == canonical({key:entry[key]
            for key in ('file','bytes','sha256')}),'batch-parent-v5-full-manifest-payload-hash')
        names.append(name)
    require(names == sorted(set(names)) and {p.name for p in folder.iterdir()} == {*names,'manifest.json'},
        'batch-parent-v5-manifest-full-directory-EOF')
    return value


def v5_batch_fixed_reference(paths,anchor,descriptors):
    # Only the accepted batch fixed manifest is a reference-only document.
    name = 'output/fixed/manifest.json'
    batch_root,old_root = paths['batch-parent-v5'],paths['continuation']
    for root in (batch_root,old_root):
        for directory in (root,root / 'output',root / 'output/fixed'):
            require(directory.is_dir() and not directory.is_symlink() and
                (directory == root or root in directory.resolve().parents),
                'batch-fixed-reference-registered-directory')
    folder,old_folder = batch_root / 'output/fixed',old_root / 'output/fixed'
    value = sealed(folder / 'manifest.json',V5_BATCH_SCHEMA + '.fixed-manifest')
    require(set(value) == {'schema','sha256','owner_sha256','source_sha256','start_sha256',
        'accepted_fixed_manifest','accepted_geometry_stage_sha256','files',
        'fixed_values_independent_of_lambda'},'batch-fixed-reference-exact-nine-fields')
    reference_inventory = scan(folder)
    require(canonical(reference_inventory) == canonical({'files':[
        {'file':'manifest.json','bytes':descriptors['fixed']['bytes'],'sha256':descriptors['fixed']['sha256']}],
        'directories':[]}) and canonical(pin(folder / 'manifest.json',name)) == canonical(descriptors['fixed']),
        'batch-fixed-reference-manifest-only-full-roster')
    require(all(value[key + '_sha256'] == descriptors[key]['sha256'] for key in ('owner','source','start')),
        'batch-fixed-reference-original-batch-owner-source-start')
    require(type(value['accepted_fixed_manifest']) is dict and
        set(value['accepted_fixed_manifest']) == {'file','bytes','sha256'} and
        canonical(value['accepted_fixed_manifest']) == canonical(anchor['fixed']) and
        canonical(pin(old_folder / 'manifest.json',name)) == canonical(anchor['fixed']),
        'batch-fixed-reference-exact-registered-old64-manifest')
    old = sealed(old_folder / 'manifest.json',LOOP_SCHEMA + '.fixed-manifest')
    require(set(old) == {'schema','sha256','owner_sha256','source_sha256','scope',
        'accepted_geometry_stage_sha256','files','fixed_values_independent_of_lambda'},
        'batch-fixed-reference-old64-exact-eight-fields')
    for key in ('owner','source'):
        require(canonical(pin(old_root / anchor[key]['file'],anchor[key]['file'])) == canonical(anchor[key]) and
            old[key + '_sha256'] == anchor[key]['sha256'],'batch-fixed-reference-original-old64-owner-source')
    old_owner = sealed(old_root / anchor['owner']['file'],LOOP_SCHEMA + '.owner')
    require(canonical(old['scope']) == canonical(old_owner['scope']) and
        old['fixed_values_independent_of_lambda'] is True and value['fixed_values_independent_of_lambda'] is True,
        'batch-fixed-reference-old-scope-and-fixed-independence')
    geometry_path = paths['oracle'] / 'output/geometry/manifest.json'
    geometry = sealed(geometry_path,'d972.r07.section-cochain-oracle.v1.stage-manifest')
    geometry_pin = pin(geometry_path,'output/geometry/manifest.json')
    require(geometry['stage'] == 'geometry' and value['accepted_geometry_stage_sha256'] ==
        old['accepted_geometry_stage_sha256'] == geometry_pin['sha256'],
        'batch-fixed-reference-registered-geometry-provenance')
    names = ['basis.json','bfs-order.u32','canonical-index.json','carry.u8','chord-edges.u32',
        'chord-tau.u8','geometry.json','next-pos.u32','p1-exponent-residues.json','parent-edge.u32',
        'parent.u32','phi.u32','potential-tau.u8','prev-pos.u32','selected-chords.u32','tag-fox.json']
    json_names = {'basis.json','canonical-index.json','geometry.json','p1-exponent-residues.json','tag-fox.json'}
    require(type(old['files']) is list and len(old['files']) == 16 and
        type(value['files']) is list and len(value['files']) == 16,'batch-fixed-reference-sixteen-descriptors')
    projected,payload_pins = [],[]
    for expected,entry in zip(names,old['files'],strict=True):
        require(type(entry) is dict and set(entry) == {'file','bytes','sha256','dtype','shape'} and
            type(entry['file']) is str and entry['file'] == expected and safe_name(entry['file']) == expected and
            type(entry['sha256']) is str and HEX.fullmatch(entry['sha256']) is not None,
            'batch-fixed-reference-old-descriptor-name-order-and-types')
        ordinary(entry['bytes'],1)
        payload = {key:entry[key] for key in ('file','bytes','sha256')}
        if expected in json_names:
            require(type(entry['dtype']) is str and entry['dtype'] == 'json' and entry['shape'] is None,
                'batch-fixed-reference-json-five-key-to-three-key-projection')
            projected.append(payload)
        else:
            require(type(entry['dtype']) is str and entry['dtype'] in ('u8','u32le') and
                type(entry['shape']) is list and entry['shape'] and
                all(type(size) is int and size > 0 for size in entry['shape']),
                'batch-fixed-reference-binary-eleven-ordinary-shape')
            require(math.prod(entry['shape']) * {'u8':1,'u32le':4}[entry['dtype']] == entry['bytes'],
                'batch-fixed-reference-binary-shape-exact-byte-EOF')
            projected.append(entry)
        payload_pins.append(payload)
    require(canonical(value['files']) == canonical(projected),'batch-fixed-reference-all-typed-descriptor-projections')
    expected_inventory = {'files':sorted(payload_pins + [pin(old_folder / 'manifest.json','manifest.json')],
        key=lambda row:row['file']),'directories':[]}
    require(canonical(scan(old_folder)) == canonical(expected_inventory),
        'batch-fixed-reference-old64-all-sixteen-full-payload-hashes-and-directory-EOF')
    save('v5-batch-fixed-reference-receipt.json',{'schema':WF_SCHEMA + '.fixed-reference-receipt.v1','status':'PASS',
        'reference':descriptors['fixed'],'accepted_fixed_manifest':anchor['fixed'],'geometry':geometry_pin,
        'reference_role':'batch-parent-v5','payload_role':'continuation','relative_directory':'output/fixed',
        'reference_inventory':reference_inventory,'payload_inventory':expected_inventory,
        'json_descriptors':5,'binary_descriptors':11,'payloads_copied_or_created':False,
        'source_executed_by_this_receipt':False,**FALSE_ASSURANCE})
    return value


def v5_batch_fixture_history(root,run):
    archive = sealed(root / 'selftest-fixtures-archive-receipt.json',V5_BATCH_WF_SCHEMA + '.selftest-fixture-archive')
    require(canonical(run['selftest_fixture_archive_receipt']) ==
        canonical(pin(root / 'selftest-fixtures-archive-receipt.json','selftest-fixtures-archive-receipt.json')),
        'batch-parent-v5-run-archive-receipt-join')
    summaries = []
    for stage in ('before-producer','before-checker','after-checker'):
        descriptor = run['selftest_fixture_comparisons'][stage]
        payload_descriptor(root,descriptor)
        comparison = sealed(root / descriptor['file'],V5_BATCH_WF_SCHEMA + '.selftest-fixture-comparison')
        require(type(comparison['stage']) is str and comparison['stage'] == stage and
            comparison['status'] == 'PASS' and comparison['errors'] == comparison['missing'] == [] and
            [row['label'] for row in comparison['fixtures']] == ['producer-selftest','checker-selftest'],
            'batch-parent-v5-historical-complete-fixture-comparison')
        if stage == 'after-checker':
            require(canonical(archive['comparison']) == canonical(descriptor),'batch-parent-v5-archive-last-comparison')
        for row in comparison['fixtures']:
            label = row['label']
            require(row['present'] is True and row['unchanged'] is True and row['state'] == 'COMPLETE' and
                row['reason'] is None and row['root'] == run['selftest_fixture_roots'][label],
                'batch-parent-v5-historical-both-complete-roots')
            for key in ('baseline','inventory'):
                payload_descriptor(root,row[key])
            baseline = sealed(root / row['baseline']['file'],V5_BATCH_WF_SCHEMA + '.selftest-fixture-baseline')
            inventory = read(root / row['inventory']['file'],True)
            require(baseline['status'] == 'PASS' and baseline['label'] == label and baseline['root'] == row['root'] and
                canonical(baseline['inventory']) == canonical(inventory),
                'batch-parent-v5-historical-exact-baseline-inventory')
            actual = scan(root / 'selftest-fixtures' / ('P' if label == 'producer-selftest' else 'C'))
            require(canonical(actual) == canonical(inventory),'batch-parent-v5-restored-complete-fixture-subtree')
            for key in ('execution','selftest'):
                payload_descriptor(root,baseline[key])
            execution = sealed(root / baseline['execution']['file'],V5_BATCH_WF_SCHEMA + '.execution-result')
            test = sealed(root / baseline['selftest']['file'],V5_BATCH_SCHEMA + '.selftest')
            require(execution['label'] == label and type(execution['exit_code']) is int and execution['exit_code'] == 0 and
                execution['outer_terminated'] is False and test['status'] == 'PASS',
                'batch-parent-v5-actual-historical-selftest-receipts-without-rerun')
        summaries.append({'stage':stage,'receipt':descriptor,'both_complete_roots_unchanged':True})
    return summaries


def v5_native_public_keys(name,value):
    require(name in V5_NATIVE_PUBLIC_KEYSETS and type(value) is dict and
        set(value) == set(V5_NATIVE_PUBLIC_KEYSETS[name]),'native-v5-original-exact-keyset:' + name)
    return value

def authenticate_v5_batch_parent(paths,inventories,anchor,code,batch_anchor,next_batch_anchor):
    root = paths['batch-parent-v5']
    registered,run = v5_batch_envelope_inventory(root)
    require(canonical(inventories['batch-parent-v5']) == canonical(registered),
        'batch-parent-v5-whole-restored-registered-inventory')
    require(sha(canonical(registered['files'])) == V5_BATCH_ROOT_REGISTRATION['files_sha256'] and
        sha(canonical(registered['directories'])) == V5_BATCH_ROOT_REGISTRATION['directories_sha256'],
        'batch-parent-v5-public-whole-inventory-list-hashes')
    expected = {item['file']:item for item in registered['files']}
    descriptors = {key:v5_batch_registered_descriptor(root,name,expected) for key,name in V5_BATCH_FIELDS.items()}
    layout = sealed(root / V5_BATCH_FIELDS['parent_layout'],V5_BATCH_SCHEMA + '.parent-layout')
    v5_native_public_keys('parent_layout',layout)
    old_parents = [{'role':role,'artifact':ARTIFACTS[role],**inventories[role]} for role in V5_PARENT_ROLES]
    require(canonical(layout['parents']) == canonical(old_parents) and canonical(layout['anchor']) == canonical(anchor) and
        canonical(layout['runtime']) == canonical(runtime()) and canonical(layout['registration']) == canonical(REGISTRATION) and
        canonical(layout['batch_anchor']) == canonical(batch_anchor) and canonical(layout['next_batch_anchor']) == canonical(next_batch_anchor),
        'batch-parent-v5-original-seventeen-parents-all-three-old-anchors-and-runtime')
    for key in ('producer_dependencies','checker_dependencies','data'):
        require(canonical(layout['code'][key]) == canonical(code[key]),'batch-parent-v5-retained-code-list:' + key)
    original_code = layout['code']
    require(canonical(original_code['producer']) == canonical({'file':'search/d972_r07_fixed_lambda_cycle_batch_v5.py',
        'bytes':366659,'sha256':'6e19d029c0f4aa55e39d24022008a29ab666c50bc52d5d086917f7dbc10cb99d'}) and
        canonical(original_code['checker']) == canonical({'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v5.py',
        'bytes':336211,'sha256':'111e23bfe6a7b49b4b3a03a00f3b48345c3f75ab098f06efc18279e881555b19'}),
        'batch-parent-v5-original-P5-C5-not-renamed-to-current')
    old_acceptance = read(root / 'acceptance.json',True)
    v5_native_public_keys('acceptance',old_acceptance)
    expected_portable = {'schema':V5_BATCH_SCHEMA + '.acceptance','parents':old_parents,'anchor':anchor,
        'batch_anchor':batch_anchor,'next_batch_anchor':next_batch_anchor,'code':original_code,'runtime':runtime(),'registration':REGISTRATION}
    require(type(old_acceptance) is dict and set(old_acceptance) == set(expected_portable) and
        canonical(portable_acceptance(old_acceptance)) == canonical(expected_portable),
        'batch-parent-v5-original-eight-key-acceptance-and-seventeen-root-projection')
    for parent in old_acceptance['parents']:
        require(type(parent) is dict and set(parent) == {'role','path','artifact','files','directories'} and
            type(parent['path']) is str and Path(parent['path']).is_absolute(),
            'batch-parent-v5-historical-host-roots-kept-in-original-acceptance')
    require(set(layout) == {'schema','sha256','parents','anchor','batch_anchor','next_batch_anchor','code','runtime','registration',
        'portable_acceptance_sha256'} and layout['portable_acceptance_sha256'] == sha(canonical(expected_portable)),
        'batch-parent-v5-complete-original-layout-seal-and-portable-sha')
    owner = sealed(root / V5_BATCH_FIELDS['owner'],V5_BATCH_SCHEMA + '.owner')
    source = sealed(root / V5_BATCH_FIELDS['source'],V5_BATCH_SCHEMA + '.source')
    v5_native_public_keys('owner',owner)
    v5_native_public_keys('source',source)
    require(owner['parent_layout_sha256'] == descriptors['parent_layout']['sha256'] and
        owner['portable_acceptance_sha256'] == layout['portable_acceptance_sha256'] and
        owner['source_sha256'] == descriptors['source']['sha256'] and
        canonical(owner['registration']) == canonical(REGISTRATION) and
        canonical(source['producer']) == canonical(original_code['producer']) and
        canonical(source['checker']) == canonical(original_code['checker']) and
        canonical(source['retained_producer_dependencies']) == canonical(P_DEPS) and
        canonical(source['retained_checker_dependencies']) == canonical(C_DEPS) and
        canonical(source['data']) == canonical(DATA) and canonical(source['runtime']) == canonical(runtime()),
        'batch-parent-v5-original-owner-source-runtime-and-retained-closure')
    previous_separator = sealed(paths['batch-parent-v4'] / NEXT_BATCH_FIELDS['separator'],NEXT_BATCH_SCHEMA + '.separator')
    original_start = sealed(root / V5_BATCH_FIELDS['start'],V5_BATCH_SCHEMA + '.start')
    require(canonical(original_start['accepted_target_derivation_parents']) ==
        canonical(previous_separator['lambda_rho2']['accepted_target_derivation_parents']),
        'batch-parent-v5-full353-ancestry-identical-to-v4-final-including-zero-scalars')
    v5_native_public_keys('start',original_start)
    old_intake = sealed(root / V5_BATCH_FIELDS['parent_intake'],V5_BATCH_SCHEMA + '.parent-intake')
    require(set(old_intake) == set(V5_NATIVE_PUBLIC_KEYSETS['parent_intake']),
        'batch-parent-v5-original-parent-intake-exact41-fields')
    native_layers = []
    for role,header,old_rank,before_count,after_count in (
            ('batch-parent',batch_anchor,1450,97,225),('batch-parent-v4',next_batch_anchor,1578,225,353)):
        native_layers.append({'role':role,'accepted_schema':header['accepted_schema'],
            'anchor_sha256':sha(canonical(header)),'head_sha256':header['head']['sha256'],
            'result_sha256':header['result']['sha256'],'checker_sha256':header['checker']['sha256'],
            'start_rank':old_rank,'rank':header['rank'],'generation':header['generation'],
            'state_head':header['state_head'],'accepted_rows':128,'target_derivation_parents_before':before_count,
            'target_derivation_parents_after':after_count,'candidate_manifests_checked':128,
            'row_manifests_checked':128,'candidate_phase_manifests_checked':768,'checkpoints_checked':772,'invocations_checked':1})
    previous_start = sealed(paths['batch-parent-v4'] / NEXT_BATCH_FIELDS['start'],NEXT_BATCH_SCHEMA + '.start')
    wanted_intake = {
        'accepted_batch_anchor_sha256':sha(canonical(batch_anchor)),
        'accepted_batch_head_sha256':batch_anchor['head']['sha256'],
        'accepted_batch_result_sha256':batch_anchor['result']['sha256'],
        'accepted_batch_checker_sha256':batch_anchor['checker']['sha256'],
        'accepted_next_batch_anchor_sha256':sha(canonical(next_batch_anchor)),
        'accepted_next_batch_head_sha256':next_batch_anchor['head']['sha256'],
        'accepted_next_batch_result_sha256':next_batch_anchor['result']['sha256'],
        'accepted_next_batch_checker_sha256':next_batch_anchor['checker']['sha256'],
        'accepted_next_batch_parent_intake_sha256':next_batch_anchor['parent_intake']['sha256'],
        'upstream_completed_steps':64,'accepted_parent_batch_rows':128,'previous_parent_batch_rows':128,
        'total_parent_batch_rows':256,'old_rank':1450,'intermediate_rank':1578,'intermediate_generation':8283,
        'rank':1706,'generation':8411,'old_target_derivation_parents':97,
        'intermediate_target_derivation_parents':225,'target_derivation_parents':353,
        'candidate_manifests_checked':256,'row_manifests_checked':256,'candidate_phase_manifests_checked':1536,
        'checkpoints_checked':1544,'invocations_checked':2,'parent_layers':native_layers,
        'native_pairing_rows_rechecked':[1450,1578,1706],
        'portable_acceptance_sha256':sha(canonical(expected_portable)),
        'old_loader_regions':registered_loader_receipt('P',parse(PREVIOUS_V5_REGISTRY_RAW)),
        'previous_target_remainder_sha256':previous_start['target_remainder_sha256'],
        'state_head':next_batch_anchor['state_head'],'target_remainder_sha256':next_batch_anchor['target_remainder_sha256'],
        'lambda_sha256':next_batch_anchor['lambda_sha256'],
        'old_anchor_head_sha256':anchor['head']['sha256'],'old_snapshot_numeric_replays':0,
        'old_batch_numeric_replays':0,'original_rho2_directly_read':False}
    require(set(old_intake) == {'schema','sha256','direct_pairing',*wanted_intake} and
        canonical({key:old_intake[key] for key in wanted_intake}) == canonical(wanted_intake) and
        original_start['parent_intake_sha256'] == descriptors['parent_intake']['sha256'],
        'batch-parent-v5-original-two-layer-1706-intake-is-not-an1834-result')
    native_pairing = old_intake['direct_pairing']
    require(type(native_pairing) is dict and set(native_pairing) == {'rows','row_pairings_sha256','lambda_pivots',
        'lambda_parent_remainder','lambda_new_remainder'} and
        canonical({key:native_pairing[key] for key in ('rows','lambda_pivots','lambda_parent_remainder','lambda_new_remainder')}) ==
        canonical({'rows':1706,'lambda_pivots':0,'lambda_parent_remainder':1,'lambda_new_remainder':1}) and
        type(native_pairing['row_pairings_sha256']) is str and HEX.fullmatch(native_pairing['row_pairings_sha256']) is not None,
        'batch-parent-v5-original-direct-pairing-receipt-public-types')
    require(canonical(run['accepted_batch_anchor']) == canonical(batch_anchor) and
        canonical(run['accepted_next_batch_anchor']) == canonical(next_batch_anchor) and
        canonical(run['accepted_artifacts']) == canonical({role:ARTIFACTS[role] for role in V5_PARENT_ROLES}),
        'batch-parent-v5-run-original-two-batch-anchors-and-seventeen-artifacts')
    receipt = sealed(root / 'source-receipt.json',V5_BATCH_WF_SCHEMA + '.source-receipt')
    require(receipt['status'] == 'PASS' and canonical(receipt['code']) == canonical(original_code) and
        canonical(receipt['runtime']) == canonical(runtime()) and canonical(receipt['launch']) == canonical(run['launch']),
        'batch-parent-v5-original-source-receipt-code-runtime-launch')
    for entry in receipt['files']:
        exact_pin(root,'checkout-sources/' + safe_name(entry['file']),{key:entry[key] for key in ('bytes','sha256')})
    require(len(receipt['files']) == 24 and canonical(receipt['files']) == canonical(code_union(original_code)),
        'batch-parent-v5-all24-original-source-and-raw-bytes')
    head = sealed(root / V5_BATCH_FIELDS['head'],V5_BATCH_SCHEMA + '.head')
    result = sealed(root / V5_BATCH_FIELDS['result'],V5_BATCH_SCHEMA + '.result')
    checked = sealed(root / V5_BATCH_FIELDS['checker'],V5_BATCH_SCHEMA + '.checker-result')
    start = sealed(root / V5_BATCH_FIELDS['start'],V5_BATCH_SCHEMA + '.start')
    final = v5_batch_saved_manifest(root / 'output/final','final-manifest')
    separator = sealed(root / V5_BATCH_FIELDS['separator'],V5_BATCH_SCHEMA + '.separator')
    selection = sealed(root / V5_BATCH_FIELDS['selection'],V5_BATCH_SCHEMA + '.selection')
    for family,value in (('head',head),('result',result),('checker_result',checked),('start',start),
            ('final_manifest',final),('separator',separator),('selection',selection)):
        v5_native_public_keys(family,value)
    selection_start = sealed(root / V5_BATCH_FIELDS['selection_start'],V5_BATCH_SCHEMA + '.selection-start')
    v5_native_public_keys('selection_start',selection_start)
    require(selection_start['selection_lambda_sha256'] == original_start['selection_lambda_sha256'] ==
        next_batch_anchor['lambda_sha256'],'native-v5-selection-lambda-comes-only-from-selection-start-and-start')
    state_fields = {'anchor_completed_steps':64,'anchor_accepted_parent_batch_rows':128,'anchor_previous_parent_batch_rows':128,'anchor_total_parent_batch_rows':256,'selected_count':128,'processed_candidates':128,
        'dependent_candidates':0,'accepted_new_rows':128,'rank':1834,'generation':8539,
        **{key:V5_BATCH_STATE[key] for key in ('state_head','target_remainder_sha256','lambda_sha256','terminal')}}
    for value in (head,result,checked,final):
        for key,wanted in state_fields.items():
            require(canonical(value[key]) == canonical(wanted),'batch-parent-v5-actual-terminal-field:' + key)
        for key,name in (('owner_sha256','owner'),('source_sha256','source'),('start_sha256','start'),
                ('selection_sha256','selection'),('selection_start_sha256','selection_start')):
            require(value[key] == descriptors[name]['sha256'],'batch-parent-v5-all-root-file-join:' + key)
    require(checked['status'] == result['status'] == 'PASS' and checked['partial'] is False and
        checked['cross_checked'] is True and checked['candidate'] is True and result['candidate'] is True and
        checked['verified'] is False and result['verified'] is False and
        checked['public_final_compared'] is True and checked['all_completed_payloads_and_json_compared'] is True and
        checked['durable_tail'] is None and checked['public_head_sha256'] == result['head_sha256'] == descriptors['head']['sha256'] and
        checked['producer_result_sha256'] == descriptors['result']['sha256'] and
        checked['final_manifest_sha256'] == result['final_manifest_sha256'] == head['final_manifest_sha256'] == descriptors['final_manifest']['sha256'],
        'batch-parent-v5-successful-whole-checker-not-just-cursor')
    require(canonical(checked['checker_source']) == canonical(original_code['checker']) and
        canonical(checked['runtime']) == canonical(runtime()) and head['kind'] == result['kind'] == final['kind'] == 'Separator' and
        head['new_lambda_oracle'] is result['new_lambda_oracle'] is separator['new_lambda_oracle'] is None,
        'batch-parent-v5-source-and-uncomputed-final-lambda-oracle')
    require(canonical({key:selection[key] for key in V5_BATCH_STATE['old_oracle']}) == canonical(V5_BATCH_STATE['old_oracle']) and
        selection['eof'] is True and ordinary(selection['chords_checked']) == 54433 and ordinary(selection['auxiliary_tests']) == 2,
        'batch-parent-v5-old-complete-54433-plus2-oracle-observation')
    require(type(start['rank']) is int and start['rank'] == 1706 and type(start['generation']) is int and start['generation'] == 8411 and start['anchor_completed_steps'] == 64 and
        start['anchor_head_sha256'] == anchor['head']['sha256'] and start['target_remainder_sha256'] == next_batch_anchor['target_remainder_sha256'] and
        start['selection_lambda_sha256'] == next_batch_anchor['lambda_sha256'],'batch-parent-v5-original1706-start-and-selection-lambda')
    derived = separator['lambda_rho2']
    require(derived['mode'] == 'derived' and type(derived['value']) is int and derived['value'] == 1 and
        derived['original_rho2_directly_read'] is False and derived['original_rho2_packed_sha256'] == start['original_rho2_packed_sha256'] and
        type(derived['accepted_target_derivation_parents']) is list and len(derived['accepted_target_derivation_parents']) == 481 and
        derived['accepted_target_derivation_parents'][:353] == start['accepted_target_derivation_parents'] and
        len(start['accepted_target_derivation_parents']) == 353,'batch-parent-v5-original353-plus128-DERIVED-not-direct-rho2')
    require(descriptors['target']['bytes'] == descriptors['lambda']['bytes'] == 12096 and
        descriptors['target']['sha256'] == V5_BATCH_STATE['target_remainder_sha256'] and
        descriptors['lambda']['sha256'] == V5_BATCH_STATE['lambda_sha256'],'batch-parent-v5-packed-target-and-lambda')
    fixed = v5_batch_fixed_reference(paths,anchor,descriptors)
    require(canonical(fixed['accepted_fixed_manifest']) == canonical(pin(paths['continuation'] / 'output/fixed/manifest.json',
        'output/fixed/manifest.json')) and fixed['fixed_values_independent_of_lambda'] is True,
        'batch-parent-v5-old-fixed-identity')
    for phase in ('section','cochain','tree'):
        saved = root / 'output/selection' / phase
        v5_batch_saved_manifest(saved,'phase-manifest')
        require(selection['phase_manifests'][phase] == digest(saved / 'manifest.json'),
            'batch-parent-v5-all-three-selection-manifest-joins')
    require(checked['selection_phases_compared'] == ['section','cochain','tree'] and
        checked['candidate_phases_compared'] == [{'ordinal':i,'phases':PHASES} for i in range(128)] and
        type(checked['candidate_decisions_compared']) is int and checked['candidate_decisions_compared'] == 128 and
        type(checked['accepted_rows_compared']) is int and checked['accepted_rows_compared'] == 128,
        'batch-parent-v5-successful-all128-decisions-rows-and768-phases')
    previous_candidate,previous_row,state,target = None,None,start['state_head'],start['target_remainder_sha256']
    for ordinal in range(128):
        folder = root / 'output/candidates' / f'{ordinal:06d}'
        candidate = sealed(folder / 'manifest.json',V5_BATCH_SCHEMA + '.candidate-manifest')
        row_folder = root / 'output/rows' / f'{ordinal:06d}'
        row = v5_batch_saved_manifest(row_folder,'row-manifest')
        require(canonical({key:candidate[key] for key in ('ordinal','outcome','rank_before','rank_after','generation_before',
            'generation_after','accepted_new_rows_before','accepted_new_rows_after')}) == canonical({'ordinal':ordinal,
                'outcome':'INDEPENDENT','rank_before':1706 + ordinal,'rank_after':1707 + ordinal,
                'generation_before':8411 + ordinal,'generation_after':8412 + ordinal,
                'accepted_new_rows_before':ordinal,'accepted_new_rows_after':ordinal + 1}),
            'batch-parent-v5-actual-each-candidate-count-transition')
        require(candidate['eof'] is True and candidate['parent_state_head'] == state and candidate['target_before_sha256'] == target and
            candidate['predecessor_candidate_manifest_sha256'] == previous_candidate and
            candidate['row_manifest_sha256'] == digest(row_folder / 'manifest.json') and
            row['predecessor_row_manifest_sha256'] == previous_row and row['candidate_ordinal'] == ordinal and
            row['local_row_offset'] == ordinal and row['global_row_id'] == 1706 + ordinal,
            'batch-parent-v5-candidate-row-full-hash-chain')
        for phase in PHASES:
            phase_folder = folder / phase if phase == 'reduction' else folder / 'e' / phase
            saved = v5_batch_saved_manifest(phase_folder,'phase-manifest')
            require(saved['phase'] == phase and saved['candidate_ordinal'] == ordinal and
                candidate['phase_manifests'][phase] == digest(phase_folder / 'manifest.json'),
                'batch-parent-v5-all768-actual-phase-manifest-files')
        instruction = sealed(row_folder / 'instruction.json',V5_BATCH_SCHEMA + '.physical-instruction')
        plain_target = read(row_folder / 'target.json',True)
        require(instruction['target_sha256'] == digest(row_folder / 'target.json') and
            instruction['physical_sha256'] == digest(row_folder / 'physical-normalized.bin') and
            plain_target['parent_remainder_sha256'] == target and
            plain_target['remainder_sha256'] == candidate['target_after_sha256'] == digest(folder / 'reduction/target-remainder.bin') and
            instruction['rolling_sha256'] == row['state_head'] == candidate['state_head'] and
            canonical(derived['accepted_target_derivation_parents'][353 + ordinal]) == canonical({
                'role':'batch-row','candidate_ordinal':ordinal,'local_row_offset':ordinal,
                'instruction_sha256':digest(row_folder / 'instruction.json'),
                'row_manifest_sha256':digest(row_folder / 'manifest.json'),
                'target_sha256':digest(row_folder / 'target.json'),'scalar':plain_target['scalar'],
                'parent_remainder_sha256':target,'remainder_sha256':candidate['target_after_sha256'],
                'state_head':candidate['state_head']}),
            'batch-parent-v5-plain-target-packed-target-row-and-DERIVED-join')
        previous_candidate,previous_row = digest(folder / 'manifest.json'),digest(row_folder / 'manifest.json')
        state,target = candidate['state_head'],candidate['target_after_sha256']
    require(state == head['state_head'] and target == head['target_remainder_sha256'] and
        final['last_candidate_manifest_sha256'] == previous_candidate and final['last_row_manifest_sha256'] == previous_row,
        'batch-parent-v5-complete128-prefix-final-state')
    for key,directory,pattern,suffix,count in (
            ('invocations','output/invocations',r'[0-9a-f]{32}\.json','invocation',1),
            ('checkpoints','output/progress/checkpoints',r'[0-9a-f]{64}\.json','checkpoint',772)):
        descriptors[key] = []
        for file in sorted((root / directory).iterdir(),key=lambda item:item.name):
            if re.fullmatch(pattern,file.name) is None:
                require(key == 'invocations' and re.fullmatch(r'\.[0-9a-f]{32}\.json\.pending-[0-9a-f]{32}',file.name),
                    'batch-parent-v5-only-registered-nonordinary-receipt')
                continue
            name = file.relative_to(root).as_posix()
            descriptor = v5_batch_registered_descriptor(root,name,expected)
            value = sealed(file,V5_BATCH_SCHEMA + '.' + suffix)
            require(value['owner_sha256'] == descriptors['owner']['sha256'] and
                value['source_sha256'] == descriptors['source']['sha256'] and value['start_sha256'] == descriptors['start']['sha256'],
                'batch-parent-v5-all-historical-invocation-checkpoint-root-joins')
            descriptors[key].append(descriptor)
        require(len(descriptors[key]) == count,'batch-parent-v5-actual-ordinary-receipt-count:' + key)
    progress = sealed(root / V5_BATCH_FIELDS['progress_head'],V5_BATCH_SCHEMA + '.progress-head')
    require(progress['sequence'] == 771 and progress['current_lambda_sha256'] is None and
        progress['kind'] == 'BatchReductionState' and progress['reduction_state_head'] == head['state_head'] and
        progress['checkpoint_sha256'] == digest(root / 'output/progress/checkpoints' / (progress['checkpoint_sha256'] + '.json')),
        'batch-parent-v5-final-real-private-checkpoint-reference')
    fixture_history = v5_batch_fixture_history(root,run)
    value = {'accepted_schema':V5_BATCH_SCHEMA,**descriptors,**copy.deepcopy(V5_BATCH_STATE)}
    require(len(value) == 36 and type(V5_BATCH_EXPECTED_HEADER) is dict and
        canonical(value) == canonical(V5_BATCH_EXPECTED_HEADER),'batch-anchor-v5-exact36-public-fields-and-all-descriptors')
    save('batch-parent-v5-envelope-intake.json',seal(WF_SCHEMA,'batch-parent-v5-envelope-intake',{
        'status':'PASS','artifact':ARTIFACTS['batch-parent-v5'],'batch_anchor_v5':value,'original_anchor':anchor,'previous_batch_anchor':batch_anchor,'previous_next_batch_anchor':next_batch_anchor,
        'input_inventory':{'files':V5_BATCH_ROOT_REGISTRATION['files'],'directories':V5_BATCH_ROOT_REGISTRATION['directories'],
            'bytes':V5_BATCH_ROOT_REGISTRATION['file_bytes']},
        'restoration':pin(REPORT / 'batch-parent-v5-restoration-result.json','batch-parent-v5-restoration-result.json'),
        'fixture_history':fixture_history,'candidate_manifests_checked':128,'row_manifests_checked':128,
        'candidate_phase_manifests_checked':768,'checkpoints_checked':772,'invocations_checked':1,
        'old_numerical_replays':0,'old_schema_renamed':False,'direct_rho2_claimed':False,**FALSE_ASSURANCE}))
    return value


