def public_output_keys(name,value):
    require(PUBLIC_V7_WIRE is not None,'root-adopted-v7-public-wire-pending')
    require(type(value) is dict and set(value) == set(PUBLIC_V7_OUTPUT_KEYS[name]),
        'public-v7-exact-output-keyset:' + name)
    return value

def final_gate():
    audit_material_bindings()
    for label in ('metadata','producer-selftest','checker-selftest','producer','checker'):
        checked_execution(label)
    for label in ('metadata','producer-selftest','checker-selftest'):
        gate = sealed(REPORT / (label + '-gate.json'),WF_SCHEMA + '.selftest-gate')
        require(gate['status'] == 'PASS' and gate['old_success_suites'] == 0,'metadata16-and-both-two-literal-plus-parent-metadata-gates')
        for field in ('execution','selftest'):
            payload_descriptor(REPORT,gate[field])
        if label == 'metadata':
            require(gate['parent1706_fixture_gate'] is None and gate['parent1834_fixture_gate'] is None and gate['parent1962_fixture_gate'] is None,'metadata-has-no-fabricated-fourth-fixture')
        else:
            again = parent1706_fixture_gate(label,sealed(REPORT / (label + '-stdout.json'),SCHEMA + '.selftest'),False)
            require(canonical(gate['parent1706_fixture_gate']) == canonical(again),
                'final-fourth-group-all-raw-fixture-and-purpose-labels-unchanged')
            again1834 = parent1834_fixture_gate(label,sealed(REPORT / (label + '-stdout.json'),SCHEMA + '.selftest'),False)
            require(canonical(gate['parent1834_fixture_gate']) == canonical(again1834),
                'final-fifth-group-all-files-directories-and-actual-purpose-labels-unchanged')
            again1962 = parent1962_fixture_gate(label,sealed(REPORT / (label + '-stdout.json'),SCHEMA + '.selftest'),False)
            require(canonical(gate['parent1962_fixture_gate']) == canonical(again1962),
                'final-sixth-group-all-files-directories-and-actual-purpose-labels-unchanged')
    require((REPORT / 'checker-stdout.json').read_bytes() == (REPORT / 'checker-result.json').read_bytes(),
        'actual-checker-stdout-equals-external-report')
    require((REPORT / 'producer-stdout.json').read_bytes() == (OUTPUT / 'result.json').read_bytes(),
        'actual-producer-stdout-equals-complete-result')
    result = sealed(OUTPUT / 'result.json',SCHEMA + '.result')
    public_output_keys('result',result)
    head = sealed(OUTPUT / 'HEAD',SCHEMA + '.head')
    public_output_keys('head',head)
    final = sealed(OUTPUT / 'final/manifest.json',SCHEMA + '.final-manifest')
    public_output_keys('final_manifest',final)
    separator = sealed(OUTPUT / 'final/separator.json',SCHEMA + '.separator')
    public_output_keys('separator',separator)
    checked = sealed(REPORT / 'checker-result.json',SCHEMA + '.checker-result')
    public_output_keys('checker_result',checked)
    acceptance = read(REPORT / 'acceptance.json',True)
    portable = portable_acceptance(acceptance)
    references = check_fixed_reference_receipts(acceptance)
    admitted = sealed(REPORT / 'acceptance-receipt.json',WF_SCHEMA + '.acceptance-receipt')
    reference_after = sealed(REPORT / 'fixed-reference-receipts-after.json',WF_SCHEMA + '.fixed-reference-receipts-after')
    require(canonical(admitted['fixed_reference_receipts']) == canonical(references) and
        canonical(reference_after['receipts']) == canonical(references) and reference_after['all_created'] is True and
        reference_after['completed_admission_inferred'] is False,'all-four-distinct-fixed-reference-receipts-final-join')
    layout = sealed(OUTPUT / 'parent-layout.json',SCHEMA + '.parent-layout')
    public_output_keys('parent_layout',layout)
    require(canonical({key:value for key,value in layout.items() if key not in ('schema','sha256')}) ==
        canonical({'portable_acceptance_sha256':sha(canonical(portable)),
            **{key:portable[key] for key in ('parents','anchor','batch_anchor','next_batch_anchor','batch_anchor_v5','batch_anchor_v6','code','runtime','registration')}}),
        'whole-portable-parent-layout-and-acceptance')
    source = sealed(OUTPUT / 'source.json',SCHEMA + '.source')
    public_output_keys('source',source)
    require(source['producer'] == code_contract()['producer'] and source['checker'] == code_contract()['checker'] and
        source['retained_producer_dependencies'] == P_DEPS and source['retained_checker_dependencies'] == C_DEPS and
        source['data'] == DATA and source['runtime'] == runtime() and
        source['retained_TCB_independence_reproved'] is False,'complete-actual-source-runtime-closure')
    start = sealed(OUTPUT / 'start.json',SCHEMA + '.start')
    public_output_keys('start',start)
    owner = sealed(OUTPUT / 'owner.json',SCHEMA + '.owner')
    public_output_keys('owner',owner)
    check_parent_intake(acceptance,start,checked)
    selection_start = sealed(OUTPUT / 'selection/start.json',SCHEMA + '.selection-start')
    public_output_keys('selection_start',selection_start)
    require(ordinary(selection_start['anchor_accepted_parent_batch_rows']) == 128,
        'new-selection-start-keeps-upstream64-and-accepted-parent128-separate')
    for key,wanted in (('anchor_previous_parent_batch_rows',384),('anchor_total_parent_batch_rows',512)):
        require(canonical(selection_start[key]) == canonical(wanted),'selection-start-separate-parent-layer-counts:' + key)
    selection = sealed(OUTPUT / 'selection/selection.json',SCHEMA + '.selection')
    public_output_keys('selection',selection)
    require(owner['registration'] == REGISTRATION and owner['portable_acceptance_sha256'] == sha(canonical(portable)) and
        owner['parent_layout_sha256'] == result['parent_layout_sha256'] == digest(OUTPUT / 'parent-layout.json'),
        'portable-owner-registration-and-layout')
    require(start['anchor_head_sha256'] == acceptance['anchor']['head']['sha256'] and
        start['anchor_result_sha256'] == acceptance['anchor']['result']['sha256'] and
        start['anchor_checker_sha256'] == acceptance['anchor']['checker']['sha256'] and
        start['rank'] == 1962 and start['generation'] == 8667 and start['anchor_completed_steps'] == 64 and
        type(start['external_e_attached']) is int and start['external_e_attached'] == 1,
        'original64-anchor-receipts-with-new1962-start-and-integer-E-count')
    for key,name in (('owner_sha256','owner.json'),('source_sha256','source.json'),('start_sha256','start.json'),
            ('selection_start_sha256','selection/start.json'),('selection_sha256','selection/selection.json')):
        require(result[key] == head[key] == final[key] == checked[key] == digest(OUTPUT / name),
            'all-complete-root-binding:' + key)
    require(checked['status'] == result['status'] == 'PASS' and checked['partial'] is False and
        checked['candidate'] is True and result['candidate'] is True and checked['cross_checked'] is True and
        result['cross_checked'] is False and checked['public_final_compared'] is True and
        checked['all_completed_payloads_and_json_compared'] is True and checked['durable_tail'] is None,
        'completed-full-comparison-candidate-scope')
    for value in (result,checked):
        require(value['grade2_member'] == value['grade2_nonmember'] == 'NOT_DECIDED' and
            value['full_A0'] is False and value['verified'] is False,'grade-and-verification-limits')
        for key in ('old_snapshot_numeric_replays','old_insert_numeric_replays','old_success_suites'):
            require(type(value[key]) is int and value[key] == 0,'no-old-arithmetic-replay:' + key)
    require(result['terminal'] in COMPLETED_TERMINALS and
        result['terminal'] == checked['terminal'] == head['terminal'] == final['terminal'],
        'exact-completed-terminal-not-workflow-status')
    for key in ('anchor_completed_steps','anchor_accepted_parent_batch_rows','anchor_previous_parent_batch_rows','anchor_total_parent_batch_rows','selected_count','processed_candidates','dependent_candidates',
            'accepted_new_rows','rank','generation','state_head','target_remainder_sha256','lambda_sha256'):
        require(canonical(result[key]) == canonical(head[key]) == canonical(final[key]) == canonical(checked[key]),
            'all-terminal-state-count-fields:' + key)
    selected = ordinary(result['selected_count'],0,128)
    processed = ordinary(result['processed_candidates'],0,selected)
    dependent = ordinary(result['dependent_candidates'],0,processed)
    accepted = ordinary(result['accepted_new_rows'],0,processed)
    require(type(result['anchor_completed_steps']) is int and result['anchor_completed_steps'] == 64 and
        type(result['rank']) is int and result['rank'] == 1962 + accepted and
        type(result['generation']) is int and result['generation'] == 8667 + accepted and
        processed == dependent + accepted,'actual-rank-generation-and-independent-dependent-counts')
    skipped = result['skipped_after_linear']
    require(type(skipped) is list and all(type(value) is int for value in skipped) and
        skipped == list(range(processed,selected)) and selected == processed + len(skipped) and
        final['skipped_after_linear'] == skipped and (selected == 0 or accepted >= 1),'whole-selected-and-skipped-partition')
    require(checked['selection_phases_compared'] == ['section','cochain','tree'] and
        checked['candidate_phases_compared'] == [{'ordinal':i,'phases':PHASES} for i in range(processed)] and
        type(checked['candidate_decisions_compared']) is int and checked['candidate_decisions_compared'] == processed and
        type(checked['accepted_rows_compared']) is int and checked['accepted_rows_compared'] == accepted,
        'all-new-selection-candidate-decision-and-row-comparisons')
    require(result['head_sha256'] == checked['public_head_sha256'] == digest(OUTPUT / 'HEAD') and
        checked['producer_result_sha256'] == digest(OUTPUT / 'result.json') and
        result['final_manifest_sha256'] == head['final_manifest_sha256'] == checked['final_manifest_sha256'] ==
        digest(OUTPUT / 'final/manifest.json'),'complete-HEAD-result-final-file-hashes')
    require(checked['checker_source'] == code_contract()['checker'] and checked['runtime'] == runtime(),
        'actual-independent-checker-source-and-runtime')
    progress = sealed(OUTPUT / 'progress/HEAD',SCHEMA + '.progress-head')
    ordinary(progress['sequence'],0,771)
    require(checked['progress_head_sha256'] == digest(OUTPUT / 'progress/HEAD') and
        progress['kind'] == 'BatchReductionState' and progress['current_lambda_sha256'] is None and
        type(progress['sequence']) is int and progress['sequence'] == 3 + 6 * processed,
        'private-prefix-retains-its-distinct-type')
    checkpoint_path = OUTPUT / 'progress/checkpoints' / (progress['checkpoint_sha256'] + '.json')
    checkpoint = sealed(checkpoint_path,SCHEMA + '.checkpoint')
    require(digest(checkpoint_path) == progress['checkpoint_sha256'],'real-final-private-checkpoint-reference')
    for key in ('processed_candidates','dependent_candidates','accepted_new_rows','rank','generation'):
        require(type(progress[key]) is int and progress[key] == result[key] == checkpoint[key],
            'committed-private-prefix-final-count:' + key)
    require(progress['reduction_state_head'] == checkpoint['reduction_state_head'] == result['state_head'] and
        progress['target_remainder_sha256'] == checkpoint['target_remainder_sha256'] == result['target_remainder_sha256'],
        'private-final-physical-chain-and-target')
    require(result['new_lambda_oracle'] is head['new_lambda_oracle'] is separator['new_lambda_oracle'] is None and
        separator['source_lower_zero'] == 'NOT_ASSERTED' and separator['physical_lower_zero'] is True,
        'new-oracle-uncomputed-and-lower-type-boundary')
    require(result['kind'] == head['kind'] == final['kind'] == separator['kind'],'terminal-kind-equality')
    if result['terminal'] == 'LINEAR_MEMBERSHIP_CANDIDATE':
        require(result['kind'] == 'LinearMembershipCandidate' and processed > 0 and accepted > 0 and
            result['positive_readout'] == 'NEW_BATCH_SAME_WORD_ADAPTER_PENDING' and
            all(separator[key] is None for key in ('lambda_sha256','lambda_rho2','direct_pairing',
                'anchor_pairing_rows','final_pairing_rows')) and result['lambda_sha256'] is None and
            result['final_lambda_characters'] is None and not (OUTPUT / 'final/lambda.bin').exists(),
            'linear-typed-null-with-positive-adapter-pending')
    else:
        require(result['kind'] == 'Separator' and result['positive_readout'] == 'NOT_APPLICABLE' and
            processed == selected and skipped == [] and
            separator['lambda_sha256'] == result['lambda_sha256'] == digest(OUTPUT / 'final/lambda.bin'),
            'completed-separator-all-candidates')
        pairing = separator['direct_pairing']
        require(set(pairing) == {'rows','row_pairings_sha256','lambda_pivots','lambda_parent_remainder','lambda_new_remainder'} and
            pairing['rows'] == result['rank'] and pairing['lambda_pivots'] == 0 and
            pairing['lambda_parent_remainder'] == pairing['lambda_new_remainder'] == 1 and
            separator['anchor_pairing_rows'] == 1962 and separator['final_pairing_rows'] == result['rank'],
            'direct-all-row-and-both-target-receipt')
        derived = separator['lambda_rho2']
        require(set(derived) == {'mode','value','original_rho2_directly_read','original_rho2_packed_sha256',
            'accepted_target_derivation_parents','identity_convention','anchor_completed_steps','anchor_accepted_parent_batch_rows',
            'anchor_previous_parent_batch_rows','anchor_total_parent_batch_rows','new_batch_target_steps_executed'} and
            derived['mode'] == 'derived' and derived['value'] == 1 and derived['original_rho2_directly_read'] is False and
            derived['original_rho2_packed_sha256'] == start['original_rho2_packed_sha256'] and
            derived['anchor_completed_steps'] == 64 and ordinary(derived['anchor_accepted_parent_batch_rows']) == 128 and
            type(derived['anchor_previous_parent_batch_rows']) is int and derived['anchor_previous_parent_batch_rows'] == 384 and
            type(derived['anchor_total_parent_batch_rows']) is int and derived['anchor_total_parent_batch_rows'] == 512 and
            derived['new_batch_target_steps_executed'] == accepted and
            len(start['accepted_target_derivation_parents']) == 609 and
            derived['accepted_target_derivation_parents'][:609] == start['accepted_target_derivation_parents'] and
            len(derived['accepted_target_derivation_parents']) == 609 + accepted,'retained609-plus-actual-new-batch-target-identities')
        if result['terminal'] == 'COMPLETE_ZERO_CANDIDATE':
            require(selected == processed == accepted == dependent == 0 and selection['terminal'] == 'COMPLETE_ZERO_CANDIDATE' and
                result['lambda_sha256'] == start['selection_lambda_sha256'],'same-current-lambda-complete-zero')
        else:
            require(selected > 0 and accepted > 0 and selection['terminal'] == 'VIOLATION_CANDIDATE',
                'nonempty-completed-batch')
    require(digest(OUTPUT / 'final/target-remainder.bin') == result['target_remainder_sha256'],
        'actual-final-packed-target-hash')
    invocations = result['invocations']
    normal_paths = []
    for file in sorted((OUTPUT / 'invocations').iterdir(),key=lambda p:p.name):
        require(file.is_file() and not file.is_symlink(),'new-invocation-file-type')
        if re.fullmatch(r'\.[0-9a-f]{32}\.json\.pending-[0-9a-f]{32}',file.name):
            continue
        require(re.fullmatch(r'[0-9a-f]{32}\.json',file.name) is not None,'new-invocation-registered-name')
        normal_paths.append(file)
    require(len(normal_paths) == len(invocations) == 1 and
        invocations[0] == pin(normal_paths[0],normal_paths[0].relative_to(OUTPUT).as_posix()) and
        invocations[0]['sha256'] == result['invocation_sha256'],'one-fresh-explicit-invocation')
    invocation = sealed(normal_paths[0],SCHEMA + '.invocation')
    require(invocation['resume'] is False and invocation['launch'] == launch() and
        invocation['host_paths'] == {'parents':read(REPORT / 'parent-roots.json',True),
            'acceptance':str(REPORT / 'acceptance.json'),'output':str(OUTPUT)} and
        invocation['acceptance_sha256'] == digest(REPORT / 'acceptance.json') and
        invocation['portable_acceptance_sha256'] == sha(canonical(portable)) and
        canonical(invocation['registration']) == canonical(REGISTRATION),'fresh-launch-and-paths-kept-outside-owner')
    for key,wanted in (('batch_size',128),('max_batches',1),('max_seconds',5400),('max_memory_mib',7168),
            ('processed_candidates_before',0),('accepted_new_rows_before',0)):
        require(type(invocation[key]) is int and invocation[key] == wanted,'fresh-registered-invocation:' + key)
    require(invocation['progress_head_before_sha256'] is None and invocation['physical_head_before_sha256'] is None,
        'fresh-has-no-before-HEAD')
    preserved = sealed(REPORT / 'preservation-result.json',WF_SCHEMA + '.preservation-result')
    require(preserved['status'] == 'PASS' and preserved['errors'] == preserved['missing'] == [] and
        preserved['acquired_parent_baselines'] == 19 and all(value is True for value in preserved['flags'].values()),
        'all-input-output-and-source-before-after-gates')
    require(preserved['flags']['both_complete_fixture_subtrees_and_entire_archive_unchanged'] is True,
        'all-selftest-fixtures-explicit-preservation-gate')
    require(preserved['flags']['all_static_audit_receipts_registry_and_history_copies_unchanged'] is True and
        preserved['flags']['all_inputs_unchanged_separately_across_P_and_C'] is True,
        'both-static-audits-and-history-explicit-before-P-between-and-after-C-gates')
    check_fixture_preservation()
    restoration = sealed(REPORT / 'batch-parent-restoration-result.json',WF_SCHEMA + '.batch-parent-restoration-result')
    require(restoration['status'] == 'PASS' and restoration['reason'] is None and
        type(restoration['created_count']) is int and restoration['created_count'] == 36 and
        restoration['all_expected_files_and_directories_reread'] is True and
        preserved['flags']['batch_parent_transport_files_unchanged_and_only_registered_directories'] is True,
        'new-parent-complete-authenticated36-restoration-and-all-ending-preservation')
    payload_descriptor(REPORT,restoration['plan'])
    next_restoration = sealed(REPORT / 'batch-parent-v4-restoration-result.json',WF_SCHEMA + '.batch-parent-v4-restoration-result')
    require(next_restoration['status'] == 'PASS' and next_restoration['reason'] is None and
        type(next_restoration['created_count']) is int and next_restoration['created_count'] == 38 and
        next_restoration['all_expected_files_and_directories_reread'] is True and
        preserved['flags']['batch_parent_v4_transport_files_unchanged_and_only_registered_directories'] is True,
        'separate-v4-complete-authenticated38-restoration-and-all-ending-preservation')
    payload_descriptor(REPORT,next_restoration['plan'])
    v5_restoration = sealed(REPORT / 'batch-parent-v5-restoration-result.json',WF_SCHEMA + '.batch-parent-v5-restoration-result')
    require(v5_restoration['status'] == 'PASS' and v5_restoration['reason'] is None and
        type(v5_restoration['created_count']) is int and v5_restoration['created_count'] == len(V5_BATCH_ABSENT_DIRECTORIES) and
        v5_restoration['all_expected_files_and_directories_reread'] is True and
        preserved['flags']['batch_parent_v5_transport_files_unchanged_and_only_registered_directories'] is True,
        'separate-v5-authenticated-registered-empty-directories-and-ending-preservation')
    payload_descriptor(REPORT,v5_restoration['plan'])
    v6_restoration = sealed(REPORT / 'batch-parent-v6-restoration-result.json',WF_SCHEMA + '.batch-parent-v6-restoration-result')
    require(v6_restoration['status'] == 'PASS' and v6_restoration['reason'] is None and
        type(v6_restoration['created_count']) is int and v6_restoration['created_count'] == len(V6_BATCH_ABSENT_DIRECTORIES) and
        v6_restoration['all_expected_files_and_directories_reread'] is True and
        preserved['flags']['batch_parent_v6_transport_files_unchanged_and_only_registered_directories'] is True,
        'separate-v6-authenticated-registered-empty-directories-and-ending-preservation')
    payload_descriptor(REPORT,v6_restoration['plan'])
    expected_preservation = {'parents_before_sha256':digest(OUTPUT / 'inputs/parents-before.json'),
        'parents_after_sha256':digest(OUTPUT / 'inputs/parents-after.json'),
        'code_before_sha256':digest(OUTPUT / 'inputs/code-before.json'),
        'code_after_sha256':digest(OUTPUT / 'inputs/code-after.json'),
        'portable_acceptance_sha256':sha(canonical(portable)),'acceptance_sha256':digest(REPORT / 'acceptance.json'),
        'all_parent_files_and_directories_unchanged':True,'all_code_and_raw_unchanged':True,'acceptance_unchanged':True}
    require(canonical(result['input_preservation']) == canonical(expected_preservation) and
        canonical(checked['input_preservation']) == canonical(expected_preservation),'P-C-own-input-preservation-receipts')
    require((OUTPUT / 'inputs/parents-before.json').read_bytes() == (REPORT / 'parent-files-before.json').read_bytes() ==
        (OUTPUT / 'inputs/parents-after.json').read_bytes() == (REPORT / 'parent-files-after.json').read_bytes() and
        (OUTPUT / 'inputs/code-before.json').read_bytes() == canonical(code_union(code_contract())) ==
        (OUTPUT / 'inputs/code-after.json').read_bytes(),'independent-full-input-inventory-bytes')
    check_batch_observation(result,checked,acceptance)
    check_cost_receipt(result)
    check_parent_timing_receipt()
    coverage_receipt(result,checked)
    return result,checked

def cost_seconds(value,label):
    require(type(value) in (int,float) and math.isfinite(value) and value >= 0,
        'cost-finite-nonnegative-seconds-no-bool:' + label)
    return value


def cost_mode():
    # Saved metadata only. Timings never launch or instrument a numerical kernel.
    inputs,errors,missing = [],[],[]
    seconds = {'producer_total':None,'producer_selection':None,
        'producer_candidate_phases':{phase:None for phase in PHASES},'producer_candidate_phase_total':None,
        'producer_final_separator':None,'producer_residual':None,'checker_total':None,'producer_plus_checker_total':None}
    counts = {'selection_expected':3,'selection_observed':0,'processed_candidates':None,
        'candidate_expected_per_phase':None,'candidate_observed_per_phase':{phase:0 for phase in PHASES},
        'final_expected':1,'final_observed':0}
    def aggregate(values,label):
        try:
            value = math.fsum(values)
            require(type(value) is float and math.isfinite(value),'cost-finite-aggregate:' + label)
            return value
        except BaseException as exc:
            errors.append({'file':'cost-aggregation:' + label,'reason':type(exc).__name__ + ':' + str(exc)})
            return None
    def observe_file(name,field,schema,required=True):
        path = REPORT / safe_name(name)
        entry = {'file':name,'pin':None,'field':field,'unit':'seconds','status':'NOT_CREATED','reason':None,'value':None}
        inputs.append(entry)
        if not path.exists():
            entry['reason'] = 'registered timing input not created'
            if required:
                missing.append(name)
            return None
        try:
            entry['pin'] = pin(path,name)
            value = sealed(path,schema)
            entry['value'] = cost_seconds(value[field],name + ':' + field)
            entry['status'] = 'OBSERVED'
            return value
        except BaseException as exc:
            entry['status'],entry['reason'] = 'INVALID',type(exc).__name__ + ':' + str(exc)
            errors.append({'file':name,'reason':entry['reason']})
            return None
    producer = observe_file('output/result.json','elapsed_seconds',SCHEMA + '.result')
    checker = observe_file('checker-result.json','elapsed_seconds',SCHEMA + '.checker-result')
    if producer is not None:
        seconds['producer_total'] = producer['elapsed_seconds']
    if checker is not None:
        seconds['checker_total'] = checker['elapsed_seconds']
    # Harness intervals are saved as distinct inputs, never subtracted as producer phases.
    for label in ('producer','checker'):
        observe_file('execution/' + label + '-result.json','elapsed_seconds',WF_SCHEMA + '.execution-result',False)
    def observe_phase(prefix,phase,descriptor):
        name = 'output/' + prefix + '/telemetry.json'
        entry = {'file':name,'pin':None,'field':'elapsed_seconds','unit':'seconds',
            'status':'NOT_CREATED','reason':None,'value':None,'manifest':None}
        inputs.append(entry)
        try:
            if (REPORT / name).exists():
                entry['pin'] = pin(REPORT / name,name)
            if (OUTPUT / prefix / 'manifest.json').exists():
                entry['manifest'] = pin(OUTPUT / prefix / 'manifest.json','output/' + prefix + '/manifest.json')
            receipt = phase_receipt(prefix,phase,descriptor)
            entry['value'] = cost_seconds(receipt['measurement']['elapsed_seconds'],name)
            entry['status'] = 'OBSERVED'
            return entry['value']
        except BaseException as exc:
            entry['status'] = 'INVALID' if (REPORT / name).exists() else 'NOT_CREATED'
            entry['reason'] = type(exc).__name__ + ':' + str(exc)
            (errors if entry['status'] == 'INVALID' else missing).append(
                {'file':name,'reason':entry['reason']} if entry['status'] == 'INVALID' else name)
            return None
    if producer is not None:
        try:
            require(type(producer['status']) is str and producer['status'] == 'PASS' and
                producer['terminal'] in COMPLETED_TERMINALS,'cost-producer-complete-result-required')
            processed = ordinary(producer['processed_candidates'],0,128)
            selected = ordinary(producer['selected_count'],processed,128)
            require(type(producer['candidates']) is list and len(producer['candidates']) == selected,
                'cost-all-selected-candidates-present')
            counts['processed_candidates'] = counts['candidate_expected_per_phase'] = processed
            require(type(producer['selection_telemetry']) is dict and
                set(producer['selection_telemetry']) == {'section','cochain','tree'},'cost-three-selection-descriptors')
            selected_times = [observe_phase('selection/' + phase,phase,producer['selection_telemetry'][phase])
                for phase in ('section','cochain','tree')]
            counts['selection_observed'] = sum(value is not None for value in selected_times)
            if counts['selection_observed'] == 3:
                seconds['producer_selection'] = aggregate(selected_times,'producer_selection')
            phase_values = {phase:[] for phase in PHASES}
            for ordinal,candidate in enumerate(producer['candidates']):
                require(type(candidate) is dict and type(candidate['ordinal']) is int and candidate['ordinal'] == ordinal,
                    'cost-ordered-candidate-ordinal')
                if ordinal >= processed:
                    require(candidate['outcome'] == 'SKIPPED_AFTER_LINEAR' and
                        canonical(candidate['phase_telemetry']) == canonical({phase:None for phase in PHASES}),
                        'cost-unprocessed-tail-has-no-manufactured-duration')
                    continue
                require(type(candidate['phase_telemetry']) is dict and set(candidate['phase_telemetry']) == set(PHASES),
                    'cost-six-descriptors-for-each-processed-candidate')
                prefix = 'candidates/' + f'{ordinal:06d}'
                for phase in PHASES:
                    value = observe_phase(prefix + ('/reduction' if phase == 'reduction' else '/e/' + phase),
                        phase,candidate['phase_telemetry'][phase])
                    if value is not None:
                        phase_values[phase].append(value)
            for phase in PHASES:
                counts['candidate_observed_per_phase'][phase] = len(phase_values[phase])
                if len(phase_values[phase]) == processed:
                    seconds['producer_candidate_phases'][phase] = aggregate(phase_values[phase],'candidate-phase:' + phase)
            if all(seconds['producer_candidate_phases'][phase] is not None for phase in PHASES):
                seconds['producer_candidate_phase_total'] = aggregate(seconds['producer_candidate_phases'].values(),'producer_candidate_phase_total')
            final = observe_phase('final','final',producer['final_telemetry'])
            if final is not None:
                counts['final_observed'] = 1
                seconds['producer_final_separator'] = final
        except BaseException as exc:
            errors.append({'file':'output/result.json','reason':type(exc).__name__ + ':' + str(exc)})
    if all(seconds[key] is not None for key in ('producer_total','producer_selection',
            'producer_candidate_phase_total','producer_final_separator')):
        seconds['producer_residual'] = aggregate([seconds['producer_total'],-seconds['producer_selection'],
            -seconds['producer_candidate_phase_total'],-seconds['producer_final_separator']],'producer_residual')
    if seconds['producer_total'] is not None and seconds['checker_total'] is not None:
        seconds['producer_plus_checker_total'] = aggregate([seconds['producer_total'],seconds['checker_total']],'producer_plus_checker_total')
    for key,value in seconds.items():
        if key != 'producer_candidate_phases' and value is not None:
            require(type(value) in (int,float) and math.isfinite(value),'cost-finite-aggregate:' + key)
    parent_context = []
    for role in ROLES:
        file = REPORT / 'acquired-parents' / (role + '.json')
        row = {'role':role,'artifact':ARTIFACTS[role],'inventory_receipt':None,
            'files':None,'directories':None,'file_bytes':None,'status':'NOT_CREATED','reason':None}
        if file.exists():
            try:
                row['inventory_receipt'] = pin(file,'acquired-parents/' + role + '.json')
                body = sealed(file,WF_SCHEMA + '.acquired-parent-before')
                require(canonical(body['artifact']) == canonical(ARTIFACTS[role]),'cost-parent-exact-artifact')
                inventory_fields({key:body[key] for key in ('files','directories')})
                row.update({'inventory_receipt':pin(file,'acquired-parents/' + role + '.json'),
                    'files':len(body['files']),'directories':len(body['directories']),
                    'file_bytes':sum(item['bytes'] for item in body['files']),'status':'OBSERVED'})
            except BaseException as exc:
                row['status'],row['reason'] = 'INVALID',type(exc).__name__ + ':' + str(exc)
                errors.append({'file':str(file.relative_to(REPORT)),'reason':row['reason']})
        else:
            row['reason'] = 'registered acquired-parent inventory not created'
            missing.append('acquired-parents/' + role + '.json')
        parent_context.append(row)
    context = {'parents':parent_context,'mathematical_parent_count':19,'original_completed_steps':64,
        'accepted_batch_layers':4,'previous_layer_rows':384,'immediate_layer_rows':128,'total_parent_batch_rows':512,
        'initial_rank':1962,'initial_generation':8667,'inherited_target_records':609,
        'current_code':code_contract(),'parent_code_versions':{
            'batch-parent':{
                'producer':{'file':'search/d972_r07_fixed_lambda_cycle_batch_v3.py','bytes':209926,
                    'sha256':'a286dca4a2d94273d2496e16317579be06173e0e4802471b2840dc4263e5a3e8'},
                'checker':{'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v3.py','bytes':178914,
                    'sha256':'1aebf6e47807466ec56426a55e34d0c7f622a5896c40184540e4d153060946d7'}},
            'batch-parent-v4':{
                'producer':{'file':'search/d972_r07_fixed_lambda_cycle_batch_v4.py','bytes':290457,
                    'sha256':'a58f7c116558fdc430025a9e095d29d0b04e0f20c9295264fca58a4c13510d0a'},
                'checker':{'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v4.py','bytes':261170,
                    'sha256':'a29380ec00876225cc618c7025d671a3da79aea3b31b829dedba13c59ba84633'}},
            'batch-parent-v5':{
                'producer':{'file':'search/d972_r07_fixed_lambda_cycle_batch_v5.py','bytes':366659,
                    'sha256':'6e19d029c0f4aa55e39d24022008a29ab666c50bc52d5d086917f7dbc10cb99d'},
                'checker':{'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v5.py','bytes':336211,
                    'sha256':'111e23bfe6a7b49b4b3a03a00f3b48345c3f75ab098f06efc18279e881555b19'}},
            'batch-parent-v6':{
                'producer':{'file':'search/d972_r07_fixed_lambda_cycle_batch_v6.py','bytes':453972,
                    'sha256':'c8a8b232acf581f0d43d26d9f6127b094235a46239ed13fcf5f73ae48d6b95a6'},
                'checker':{'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v6.py','bytes':428108,
                    'sha256':'59d525f7320b5efe19c55d8a567335e9f5ded8cb19124fe75dda5aa8c70dccbb'}}},
        'native_pairing_rows_public_contract':{'producer':[1450,1578,1706,1834,1962],'checker':[1450,1578,1706,1834,1962]},
        'C5_adds_explicit_native1450_and1578_pairing_calls':True,
        'new_nineteenth_parent_and_adapter_added':True,'controlled_single_parent_replacement':False,
        'prior_v4_producer_residual_seconds':232.786064,'prior_value_is_current_expected_value':False}
    complete = (producer is not None and checker is not None and producer.get('status') == 'PASS' and
        checker.get('status') == 'PASS' and checker.get('partial') is False and
        all(seconds[key] is not None for key in seconds if key != 'producer_candidate_phases'))
    negative = seconds['producer_residual'] is not None and seconds['producer_residual'] < 0
    status = 'INVALID_METADATA' if errors else 'INCOMPLETE' if missing or not complete else 'NEGATIVE_RESIDUAL' if negative else 'PASS'
    reason = None if status == 'PASS' else {'errors':errors,'missing':missing,'complete_measurement':complete,
        'negative_residual_observed':negative,'negative_value_clamped':False}
    save('cost-receipt.json',seal(WF_SCHEMA,'cost-receipt',{
        'status':status,'reason':reason,'launch':launch(),'registration':REGISTRATION,'inputs':inputs,
        'seconds':seconds,'phase_counts':counts,'context':context,
        'measurement_scope':'seconds from sealed saved P/C elapsed and full P phase metadata; timing aggregation only',
        'limitations':['P residual is P total minus P selection, six candidate phases and final separator',
            'C phase timestamps are absent; no C residual or P+C unmeasured subtotal is inferred',
            'partial inputs remain null; a signed negative residual is never clamped',
            'nineteenth parent, adapter and native pairing calls are confounders',
            'one observation does not decide a causal timing model; no expected-second threshold is a gate'],
        **FALSE_ASSURANCE}))
    return 0


