def v6_batch_registration():
    value = V6_BATCH_ROOT_REGISTRATION
    require(type(value) is dict and set(value) == {'files','file_bytes','directories',
        'files_sha256','directories_sha256'},'batch-parent-v6-formal-five-key-inventory-pending')
    for key in ('files','file_bytes','directories'):
        ordinary(value[key],1)
    for key in ('files_sha256','directories_sha256'):
        require(type(value[key]) is str and HEX.fullmatch(value[key]) is not None,
            'batch-parent-v6-formal-inventory-hash-type')
    require(value['files'] == 11915 and value['file_bytes'] == 1395498726,
        'batch-parent-v6-complete-acquired-file-count-and-byte-total')
    require(type(V6_BATCH_ABSENT_DIRECTORIES) is list and
        V6_BATCH_ABSENT_DIRECTORIES == sorted(set(V6_BATCH_ABSENT_DIRECTORIES)) and
        all(safe_name(name) == name for name in V6_BATCH_ABSENT_DIRECTORIES),
        'batch-parent-v6-registered-empty-directory-list-pending')
    return value


def v6_batch_transport_pins(root):
    entries = {}
    for name,(length,checksum) in V6_BATCH_TRANSPORT_PINS.items():
        exact_pin(root,name,{'bytes':length,'sha256':checksum})
        entries[name] = {'file':name,'bytes':length,'sha256':checksum}
    return entries


def v6_batch_envelope_inventory(root):
    registration = v6_batch_registration()
    for name in ('run-receipt.json','envelope-inventory-before-run.json'):
        length,checksum = V6_BATCH_TRANSPORT_PINS[name]
        exact_pin(root,name,{'bytes':length,'sha256':checksum})
    run = sealed(root / 'run-receipt.json',V6_BATCH_WF_SCHEMA + '.run-receipt')
    require(type(run['status']) is str and run['status'] == 'PASS','batch-parent-v6-successful-envelope')
    spec = ARTIFACTS['batch-parent-v6']
    require(canonical(run['launch']) == canonical({'run':spec['run'],'attempt':spec['attempt'],
        'head':spec['head'],'workflow':spec['workflow']}),'batch-parent-v6-original-native-launch')
    before = read(root / 'envelope-inventory-before-run.json',True)
    names,dirs = inventory_fields(before)
    require(names == sorted(names) and dirs == sorted(dirs) and len(names) == registration['files'] - 2 and
        len(dirs) == registration['directories'],'batch-parent-v6-original-complete-inventory-counts')
    excludes = ['envelope-inventory-before-run.json','run-receipt.json']
    payload_bytes = registration['file_bytes'] - sum(V6_BATCH_TRANSPORT_PINS[name][0] for name in excludes)
    require(canonical(run['envelope_payload_before_this_receipt']) == canonical({
        'bytes':payload_bytes,'directories':registration['directories'],'files':registration['files'] - 2,
        'excludes':excludes,'inventory':{'file':excludes[0],'bytes':V6_BATCH_TRANSPORT_PINS[excludes[0]][0],
            'sha256':V6_BATCH_TRANSPORT_PINS[excludes[0]][1]}}),'batch-parent-v6-envelope-self-exclusion')
    require(sum(entry['bytes'] for entry in before['files']) == payload_bytes and
        set(excludes).isdisjoint(names),'batch-parent-v6-original-payload-bytes')
    files = copy.deepcopy(before['files'])
    files.extend({'file':name,'bytes':V6_BATCH_TRANSPORT_PINS[name][0],
        'sha256':V6_BATCH_TRANSPORT_PINS[name][1]} for name in excludes)
    files.sort(key=lambda item:item['file'])
    value = {'files':files,'directories':dirs}
    validate_inventory(value,{entry['file']:entry for entry in files},set(dirs))
    require(len(files) == registration['files'] and sum(item['bytes'] for item in files) == registration['file_bytes'] and
        sha(canonical(files)) == registration['files_sha256'] and sha(canonical(dirs)) == registration['directories_sha256'],
        'batch-parent-v6-full-files-and-restored-directories-exact-formal-registration')
    return value,run

def v6_batch_inner_zip_read(root,inventory):
    names,dirs = inventory_fields(inventory)
    require(names == sorted(names) and dirs == sorted(dirs) and len(names) > 0 and len(dirs) > 0,
        'batch-parent-v6-inner-fixture-roster')
    files = {entry['file']:entry for entry in inventory['files']}
    expected_dirs,seen_files,seen_dirs,folded = set(dirs),set(),set(),set()
    total = 0
    with zipfile.ZipFile(root / 'selftest-fixtures.zip') as archive:
        infos = archive.infolist()
        require(len(infos) == len(names) + len(dirs),'batch-parent-v6-inner-all-entry-count')
        for info in infos:
            directory = info.is_dir()
            name = safe_name(info.filename[:-1] if directory else info.filename)
            require(info.orig_filename == info.filename and name.split('/')[0] in ('P','C') and
                info.filename == name + ('/' if directory else '') and name.casefold() not in folded and
                not info.flag_bits & 1,'batch-parent-v6-inner-name-owner-and-unique')
            folded.add(name.casefold())
            kind = stat.S_IFMT((info.external_attr >> 16) & 0xffff)
            require(kind == (stat.S_IFDIR if directory else stat.S_IFREG),'batch-parent-v6-inner-exact-entry-type')
            require((directory and name in expected_dirs and info.file_size == 0) or
                (not directory and name in files and info.file_size == files[name]['bytes']),
                'batch-parent-v6-inner-registered-entry-and-size')
            checksum,size = hashlib.sha256(),0
            with archive.open(info) as stream:
                while True:
                    block = stream.read(1 << 20)
                    if not block:
                        break
                    size += len(block)
                    require(size <= info.file_size,'batch-parent-v6-inner-stream-size-bound')
                    checksum.update(block)
            require(size == info.file_size,'batch-parent-v6-inner-full-EOF-and-CRC')
            if directory:
                seen_dirs.add(name)
            else:
                require(checksum.hexdigest() == files[name]['sha256'],'batch-parent-v6-inner-whole-file-SHA')
                seen_files.add(name)
                total += size
    require(seen_files == set(files) and seen_dirs == expected_dirs,'batch-parent-v6-inner-exact-all-files-directories')
    return {'entries':len(names) + len(dirs),'files':len(files),'directories':len(dirs),'bytes':total,
        'every_entry_full_EOF_CRC_and_SHA':True,'ignored_entries':[]}


def restore_v6_batch_parent_directories(root,extraction):
    # Authenticate every existing byte and every registered missing directory before the first mkdir.
    begun = time.monotonic()
    registration = v6_batch_registration()
    pins = v6_batch_transport_pins(root)
    wanted,run = v6_batch_envelope_inventory(root)
    before = scan(root)
    require(canonical(before['files']) == canonical(wanted['files']),
        'batch-parent-v6-all-11915-files-authenticated-before-directory-restoration')
    ancestors = set()
    for entry in wanted['files']:
        parent = PurePosixPath(entry['file']).parent
        while str(parent) != '.':
            ancestors.add(str(parent))
            parent = parent.parent
    require(type(extraction['entries']) is int and extraction['entries'] == registration['files'] and
        extraction['expanded_bytes'] == registration['file_bytes'] and extraction['full_EOF'] is True and
        len(ancestors) == 3538 and set(before['directories']) == ancestors,
        'batch-parent-v6-original-file-only-ZIP-and-3538-implicit-directories')
    missing = sorted(set(wanted['directories']) - ancestors)
    require(ancestors <= set(wanted['directories']) and missing == V6_BATCH_ABSENT_DIRECTORIES and len(missing) == registration['directories'] - 3538,
        'batch-parent-v6-only-formally-registered-missing-directories')
    controls = read(root / 'intake-controls-before.json',True)
    inventory_fields(controls)
    require(set(missing) <= set(controls['directories']),'batch-parent-v6-all-missing-directories-in-original-pre-P-controls')
    inventory = read(root / 'selftest-fixtures-inventory.json',True)
    projected = {'files':[dict(item,file=item['file'][18:]) for item in wanted['files']
        if item['file'].startswith('selftest-fixtures/')],
        'directories':[name[18:] for name in wanted['directories'] if name.startswith('selftest-fixtures/')]}
    require(canonical(projected) == canonical(inventory) and
        (root / 'selftest-fixtures-inventory.json').read_bytes() ==
        (root / 'selftest-fixtures-archive-readback.json').read_bytes() ==
        (root / 'selftest-fixtures-after-archive.json').read_bytes(),'batch-parent-v6-three-inner-inventories-and-envelope-projection')
    archived = sealed(root / 'selftest-fixtures-archive-receipt.json',V6_BATCH_WF_SCHEMA + '.selftest-fixture-archive')
    require(type(archived['status']) is str and archived['status'] == 'PASS' and archived['reason'] is None and
        archived['excluded_entries'] == [] and all(archived[key] is True for key in (
            'all_entries_and_explicit_directories_read','all_file_bytes_SHA_EOF_and_CRC_read',
            'both_completed_roots_unchanged','container_present','raw_fixtures_retained')) and
        all(archived[key] is False for key in ('archive_contains_itself','partial_or_missing_roots_claimed_complete',
            'silently_filtered_entries',*FALSE_ASSURANCE)),'batch-parent-v6-actual-complete-fixture-archive')
    for key,name in (('inventory','selftest-fixtures-inventory.json'),
            ('readback_inventory','selftest-fixtures-archive-readback.json'),
            ('after_inventory','selftest-fixtures-after-archive.json'),('archive','selftest-fixtures.zip')):
        require(canonical(archived[key]) == canonical(pins[name]) and
            canonical(run['selftest_fixture_archive_files'][name]) == canonical(pins[name]),
            'batch-parent-v6-archive-run-exact-file-pin:' + key)
    inner = v6_batch_inner_zip_read(root,inventory)
    plan = sorted(missing,key=lambda name:(len(PurePosixPath(name).parts),name))
    planned,base = set(),root.resolve()
    for name in plan:
        target = root / safe_name(name)
        require(base in target.resolve().parents and not target.exists() and not target.is_symlink(),
            'batch-parent-v6-new-directory-contained-and-absent')
        parent = target.parent
        relative_parent = parent.relative_to(root).as_posix()
        require((parent.is_dir() and not parent.is_symlink()) or relative_parent in planned,
            'batch-parent-v6-all-directory-parents-planned-first')
        planned.add(name)
    save('batch-parent-v6-restoration-plan.json',seal(WF_SCHEMA,'batch-parent-v6-restoration-plan',{
        'artifact':ARTIFACTS['batch-parent-v6'],'root':str(base),'source_pins':pins,'original_files':registration['files'],
        'original_directories':3538,'expected_directories':registration['directories'],'missing':plan,'inner_zip':inner,
        'all_file_bytes_authenticated_before_first_mkdir':True,'only_registered_missing_directories':True,
        'old_numerical_replays':0,**FALSE_ASSURANCE}))
    created = []
    try:
        for ordinal,name in enumerate(plan):
            target = root / name
            require(target.parent.is_dir() and not target.parent.is_symlink() and not target.exists() and
                not target.is_symlink(),'batch-parent-v6-directory-create-boundary')
            returned = os.mkdir(target)
            require(returned is None and target.is_dir() and not target.is_symlink() and
                target.resolve() == base.joinpath(*PurePosixPath(name).parts),
                'batch-parent-v6-directory-return-and-immediate-exists')
            row = {'ordinal':ordinal,'relative':name,'resolved_path':str(target.resolve()),
                'mkdir_return':None,'immediate_exists':True,'regular_directory':True}
            created.append(row)
            save('batch-parent-v6-restoration/' + str(ordinal).zfill(2) + '.json',row)
        after = scan(root)
        require(canonical(after) == canonical(wanted),'batch-parent-v6-full-reread-after-directory-restoration')
        require(canonical(scan(root / 'selftest-fixtures')) == canonical(inventory),
            'batch-parent-v6-full-fixture-reread-after-directory-restoration')
        status,reason = 'PASS',None
    except BaseException as exc:
        status,reason = 'FAIL',type(exc).__name__ + ':' + str(exc)
        raise
    finally:
        save('batch-parent-v6-restoration-result.json',seal(WF_SCHEMA,'batch-parent-v6-restoration-result',{
            'status':status,'reason':reason,'plan':pin(REPORT / 'batch-parent-v6-restoration-plan.json',
                'batch-parent-v6-restoration-plan.json'),'created':created,'created_count':len(created),
            'all_expected_files_and_directories_reread':status == 'PASS','elapsed_seconds':time.monotonic() - begun,
            'mathematical_replays':0,**FALSE_ASSURANCE}))
    return pin(REPORT / 'batch-parent-v6-restoration-result.json','batch-parent-v6-restoration-result.json')


def v6_batch_registered_descriptor(root,name,expected_files):
    name = safe_name(name)
    require(name in expected_files,'batch-parent-v6-registered-file:' + name)
    expected = expected_files[name]
    require(canonical(pin(root / name,name)) == canonical(expected),'batch-parent-v6-actual-file-pin:' + name)
    return copy.deepcopy(expected)


def v6_batch_saved_manifest(folder,suffix):
    value = sealed(folder / 'manifest.json',V6_BATCH_SCHEMA + '.' + suffix)
    require(value.get('eof',True) is True and type(value['files']) is list,'batch-parent-v6-manifest-full-EOF')
    names = []
    for entry in value['files']:
        require(type(entry) is dict and set(entry) in ({'file','bytes','sha256'},
            {'file','bytes','sha256','dtype','shape'}),'batch-parent-v6-manifest-descriptor-shape')
        name = safe_name(entry['file'])
        require('/' not in name and type(entry['bytes']) is int and entry['bytes'] >= 0 and
            type(entry['sha256']) is str and HEX.fullmatch(entry['sha256']) is not None,
            'batch-parent-v6-manifest-descriptor-types')
        require(canonical(pin(folder / name,name)) == canonical({key:entry[key]
            for key in ('file','bytes','sha256')}),'batch-parent-v6-full-manifest-payload-hash')
        names.append(name)
    require(names == sorted(set(names)) and {p.name for p in folder.iterdir()} == {*names,'manifest.json'},
        'batch-parent-v6-manifest-full-directory-EOF')
    return value


def v6_batch_fixed_reference(paths,anchor,descriptors):
    # Only the accepted batch fixed manifest is a reference-only document.
    name = 'output/fixed/manifest.json'
    batch_root,old_root = paths['batch-parent-v6'],paths['continuation']
    for root in (batch_root,old_root):
        for directory in (root,root / 'output',root / 'output/fixed'):
            require(directory.is_dir() and not directory.is_symlink() and
                (directory == root or root in directory.resolve().parents),
                'batch-fixed-reference-registered-directory')
    folder,old_folder = batch_root / 'output/fixed',old_root / 'output/fixed'
    value = sealed(folder / 'manifest.json',V6_BATCH_SCHEMA + '.fixed-manifest')
    require(set(value) == {'schema','sha256','owner_sha256','source_sha256','start_sha256',
        'accepted_fixed_manifest','accepted_geometry_stage_sha256','files',
        'fixed_values_independent_of_lambda'},'batch-fixed-reference-exact-nine-fields')
    reference_inventory = scan(folder)
    require(canonical(reference_inventory) == canonical({'files':[
        {'file':'manifest.json','bytes':descriptors['fixed']['bytes'],'sha256':descriptors['fixed']['sha256']}],
        'directories':[]}) and canonical(pin(folder / 'manifest.json',name)) == canonical(descriptors['fixed']),
        'batch-fixed-reference-manifest-only-full-roster')
    require(all(value[key + '_sha256'] == descriptors[key]['sha256'] for key in ('owner','source','start')),
        'batch-fixed-reference-original-batch-owner-source-start')
    require(type(value['accepted_fixed_manifest']) is dict and
        set(value['accepted_fixed_manifest']) == {'file','bytes','sha256'} and
        canonical(value['accepted_fixed_manifest']) == canonical(anchor['fixed']) and
        canonical(pin(old_folder / 'manifest.json',name)) == canonical(anchor['fixed']),
        'batch-fixed-reference-exact-registered-old64-manifest')
    old = sealed(old_folder / 'manifest.json',LOOP_SCHEMA + '.fixed-manifest')
    require(set(old) == {'schema','sha256','owner_sha256','source_sha256','scope',
        'accepted_geometry_stage_sha256','files','fixed_values_independent_of_lambda'},
        'batch-fixed-reference-old64-exact-eight-fields')
    for key in ('owner','source'):
        require(canonical(pin(old_root / anchor[key]['file'],anchor[key]['file'])) == canonical(anchor[key]) and
            old[key + '_sha256'] == anchor[key]['sha256'],'batch-fixed-reference-original-old64-owner-source')
    old_owner = sealed(old_root / anchor['owner']['file'],LOOP_SCHEMA + '.owner')
    require(canonical(old['scope']) == canonical(old_owner['scope']) and
        old['fixed_values_independent_of_lambda'] is True and value['fixed_values_independent_of_lambda'] is True,
        'batch-fixed-reference-old-scope-and-fixed-independence')
    geometry_path = paths['oracle'] / 'output/geometry/manifest.json'
    geometry = sealed(geometry_path,'d972.r07.section-cochain-oracle.v1.stage-manifest')
    geometry_pin = pin(geometry_path,'output/geometry/manifest.json')
    require(geometry['stage'] == 'geometry' and value['accepted_geometry_stage_sha256'] ==
        old['accepted_geometry_stage_sha256'] == geometry_pin['sha256'],
        'batch-fixed-reference-registered-geometry-provenance')
    names = ['basis.json','bfs-order.u32','canonical-index.json','carry.u8','chord-edges.u32',
        'chord-tau.u8','geometry.json','next-pos.u32','p1-exponent-residues.json','parent-edge.u32',
        'parent.u32','phi.u32','potential-tau.u8','prev-pos.u32','selected-chords.u32','tag-fox.json']
    json_names = {'basis.json','canonical-index.json','geometry.json','p1-exponent-residues.json','tag-fox.json'}
    require(type(old['files']) is list and len(old['files']) == 16 and
        type(value['files']) is list and len(value['files']) == 16,'batch-fixed-reference-sixteen-descriptors')
    projected,payload_pins = [],[]
    for expected,entry in zip(names,old['files'],strict=True):
        require(type(entry) is dict and set(entry) == {'file','bytes','sha256','dtype','shape'} and
            type(entry['file']) is str and entry['file'] == expected and safe_name(entry['file']) == expected and
            type(entry['sha256']) is str and HEX.fullmatch(entry['sha256']) is not None,
            'batch-fixed-reference-old-descriptor-name-order-and-types')
        ordinary(entry['bytes'],1)
        payload = {key:entry[key] for key in ('file','bytes','sha256')}
        if expected in json_names:
            require(type(entry['dtype']) is str and entry['dtype'] == 'json' and entry['shape'] is None,
                'batch-fixed-reference-json-five-key-to-three-key-projection')
            projected.append(payload)
        else:
            require(type(entry['dtype']) is str and entry['dtype'] in ('u8','u32le') and
                type(entry['shape']) is list and entry['shape'] and
                all(type(size) is int and size > 0 for size in entry['shape']),
                'batch-fixed-reference-binary-eleven-ordinary-shape')
            require(math.prod(entry['shape']) * {'u8':1,'u32le':4}[entry['dtype']] == entry['bytes'],
                'batch-fixed-reference-binary-shape-exact-byte-EOF')
            projected.append(entry)
        payload_pins.append(payload)
    require(canonical(value['files']) == canonical(projected),'batch-fixed-reference-all-typed-descriptor-projections')
    expected_inventory = {'files':sorted(payload_pins + [pin(old_folder / 'manifest.json','manifest.json')],
        key=lambda row:row['file']),'directories':[]}
    require(canonical(scan(old_folder)) == canonical(expected_inventory),
        'batch-fixed-reference-old64-all-sixteen-full-payload-hashes-and-directory-EOF')
    save('v6-batch-fixed-reference-receipt.json',{'schema':WF_SCHEMA + '.fixed-reference-receipt.v1','status':'PASS',
        'reference':descriptors['fixed'],'accepted_fixed_manifest':anchor['fixed'],'geometry':geometry_pin,
        'reference_role':'batch-parent-v6','payload_role':'continuation','relative_directory':'output/fixed',
        'reference_inventory':reference_inventory,'payload_inventory':expected_inventory,
        'json_descriptors':5,'binary_descriptors':11,'payloads_copied_or_created':False,
        'source_executed_by_this_receipt':False,**FALSE_ASSURANCE})
    return value


def v6_batch_fixture_history(root,run):
    archive = sealed(root / 'selftest-fixtures-archive-receipt.json',V6_BATCH_WF_SCHEMA + '.selftest-fixture-archive')
    require(canonical(run['selftest_fixture_archive_receipt']) ==
        canonical(pin(root / 'selftest-fixtures-archive-receipt.json','selftest-fixtures-archive-receipt.json')),
        'batch-parent-v6-run-archive-receipt-join')
    summaries = []
    for stage in ('before-producer','before-checker','after-checker'):
        descriptor = run['selftest_fixture_comparisons'][stage]
        payload_descriptor(root,descriptor)
        comparison = sealed(root / descriptor['file'],V6_BATCH_WF_SCHEMA + '.selftest-fixture-comparison')
        require(type(comparison['stage']) is str and comparison['stage'] == stage and
            comparison['status'] == 'PASS' and comparison['errors'] == comparison['missing'] == [] and
            [row['label'] for row in comparison['fixtures']] == ['producer-selftest','checker-selftest'],
            'batch-parent-v6-historical-complete-fixture-comparison')
        if stage == 'after-checker':
            require(canonical(archive['comparison']) == canonical(descriptor),'batch-parent-v6-archive-last-comparison')
        for row in comparison['fixtures']:
            label = row['label']
            require(row['present'] is True and row['unchanged'] is True and row['state'] == 'COMPLETE' and
                row['reason'] is None and row['root'] == run['selftest_fixture_roots'][label],
                'batch-parent-v6-historical-both-complete-roots')
            for key in ('baseline','inventory'):
                payload_descriptor(root,row[key])
            baseline = sealed(root / row['baseline']['file'],V6_BATCH_WF_SCHEMA + '.selftest-fixture-baseline')
            inventory = read(root / row['inventory']['file'],True)
            require(baseline['status'] == 'PASS' and baseline['label'] == label and baseline['root'] == row['root'] and
                canonical(baseline['inventory']) == canonical(inventory),
                'batch-parent-v6-historical-exact-baseline-inventory')
            actual = scan(root / 'selftest-fixtures' / ('P' if label == 'producer-selftest' else 'C'))
            require(canonical(actual) == canonical(inventory),'batch-parent-v6-restored-complete-fixture-subtree')
            for key in ('execution','selftest'):
                payload_descriptor(root,baseline[key])
            execution = sealed(root / baseline['execution']['file'],V6_BATCH_WF_SCHEMA + '.execution-result')
            test = sealed(root / baseline['selftest']['file'],V6_BATCH_SCHEMA + '.selftest')
            require(execution['label'] == label and type(execution['exit_code']) is int and execution['exit_code'] == 0 and
                execution['outer_terminated'] is False and test['status'] == 'PASS',
                'batch-parent-v6-actual-historical-selftest-receipts-without-rerun')
        summaries.append({'stage':stage,'receipt':descriptor,'both_complete_roots_unchanged':True})
    return summaries


def v6_native_public_keys(name,value):
    require(name in V6_NATIVE_PUBLIC_KEYSETS and type(value) is dict and
        set(value) == set(V6_NATIVE_PUBLIC_KEYSETS[name]),'native-v6-original-exact-keyset:' + name)
    return value


