# Task1149: finite sixth-group serialized metadata reception; no helper or vector replay.
def v7_sixth_same(actual,expected,label):
    require(canonical(actual) == canonical(expected),'sixth-exact-typed-public-value:' + label)

def v7_sixth_seal(value):
    require(type(value) is dict and 'sha256' not in value,'sixth-unsigned-public-object')
    return {**value,'sha256':sha(canonical(value))}

def v7_sixth_read(root,name,expected):
    value = read(root / safe_name(name),True)
    v7_sixth_same(value,expected,name)
    return value

def v7_sixth_directories(names,extra=()):
    directories = set(extra)
    for name in names:
        parent = PurePosixPath(safe_name(name)).parent
        while str(parent) != '.':
            directories.add(str(parent));parent = parent.parent
    return sorted(directories)

def v7_sixth_selftest(label,selftest):
    contract = P_SIXTH_SERIALIZER['selftest_result'] if label == 'producer-selftest' else C_SIXTH_SERIALIZER['actual_selftest_result']
    keys = contract['whole_exact_keys'] if label == 'producer-selftest' else contract['exact_keys']
    require(type(selftest) is dict and set(selftest) == set(keys),'sixth-selftest-whole11-fields')
    for key,expected in contract['fixed_values'].items():
        v7_sixth_same(selftest[key],expected,label + ':' + key)
    expected = contract['sixth_exact_value'] if label == 'producer-selftest' else contract['sixth_group_value']
    require(type(selftest['tests']) is list and len(selftest['tests']) == 6,'sixth-six-groups-in-original-order')
    v7_sixth_same(selftest['tests'][5],expected,'sixth-result-index5-not-invented-top-key')

def v7_p_sixth_expected():
    contract = P_SIXTH_SERIALIZER
    expected = {name:copy.deepcopy(row['exact_value']) for name,row in
        contract['positive_json_documents_relative_to_positive'].items() if 'exact_value' in row}
    old = copy.deepcopy(expected['current.json'])
    old['parents'] = [{key:value for key,value in row.items() if key != 'path'} for row in old['parents'][:18]]
    expected['old18.json'] = old
    prefix = []
    for index in range(97):
        token = sha(('synthetic-native-prefix-' + str(index)).encode('ascii'))
        row = {'role':'base' if index < 32 else 'external-e' if index == 32 else 'step',
            'manifest_sha256':token,'result_sha256':token,'target_sha256':token,'state_head':token}
        if index >= 32:
            row['instruction_sha256'] = token
        prefix.append(row)
    for index in range(384):
        layer,ordinal = divmod(index,128)
        token = sha(('synthetic-prior-layer-' + str(layer) + '-' + str(ordinal)).encode('ascii'))
        prefix.append({'role':'batch-row','candidate_ordinal':ordinal,'local_row_offset':ordinal,
            'row_manifest_sha256':token,'instruction_sha256':token,'target_sha256':token,
            'parent_remainder_sha256':token,'remainder_sha256':token,'scalar':0 if ordinal == 0 else 1,'state_head':token})
    appended = []
    for ordinal in range(128):
        token = sha(('synthetic-v6-target-' + str(ordinal)).encode('ascii'))
        appended.append({'role':'batch-row','candidate_ordinal':ordinal,'local_row_offset':ordinal,
            'row_manifest_sha256':token,'instruction_sha256':token,'target_sha256':token,
            'parent_remainder_sha256':token,'remainder_sha256':token,'scalar':0 if ordinal == 0 else 1,'state_head':token})
    expected.update({'prefix481.json':prefix,'appended128.json':appended,'parents609.json':prefix + appended})
    return expected

def producer1962_fixture_gate(root,selftest):
    contract = P_SIXTH_SERIALIZER
    v7_sixth_selftest('producer-selftest',selftest)
